#!/usr/bin/env python3
"""Independent OOXML inputs; never generated by the application's export path."""
import hashlib
import json
from datetime import datetime
from io import BytesIO
from pathlib import Path
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo

from openpyxl import Workbook
from openpyxl.styles import Alignment, Font, PatternFill

ROOT = Path(__file__).resolve().parent


def stable_zip(path, entries):
    with ZipFile(path, "w", ZIP_DEFLATED) as archive:
        for name, content in sorted(entries.items()):
            info = ZipInfo(name, (2024, 1, 1, 0, 0, 0))
            info.compress_type = ZIP_DEFLATED
            archive.writestr(info, content)


stable_zip(ROOT / "viewport-source.docx", {
    "[Content_Types].xml": '''<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>''',
    "_rels/.rels": '''<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>''',
    "word/document.xml": '''<?xml version="1.0" encoding="UTF-8"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>
<w:p><w:pPr><w:spacing w:after="400"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Liberation Sans" w:hAnsi="Liberation Sans"/><w:color w:val="D40A8E"/><w:sz w:val="32"/></w:rPr><w:t>VIEWPORT</w:t></w:r></w:p>
<w:p><w:pPr><w:ind w:left="300"/><w:spacing w:after="240"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Liberation Sans" w:hAnsi="Liberation Sans"/><w:color w:val="7541C8"/><w:sz w:val="32"/></w:rPr><w:t>ANCHOR</w:t></w:r></w:p>
<w:p><w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>WORD_SENTINEL</w:t></w:r></w:p>
<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720" w:header="360" w:footer="360" w:gutter="0"/></w:sectPr>
</w:body></w:document>''',
})

book = Workbook()
book.properties.created = book.properties.modified = datetime(2024, 1, 1)
sheet = book.active
sheet.title = "Viewport"
sheet.sheet_view.zoomScale = 100
for column in ("A", "B", "C"):
    sheet.column_dimensions[column].width = 11
for row in range(1, 6):
    sheet.row_dimensions[row].height = 30
sheet["A1"] = "ORIGIN"
sheet["B2"] = 25
sheet["B2"].fill = PatternFill("solid", fgColor="20B2AA")
sheet["B2"].font = Font(name="Liberation Sans", size=12, color="000000")
sheet["B2"].alignment = Alignment(horizontal="center", vertical="center")
sheet["A4"] = "KEEP"
sheet["A4"].fill = PatternFill("solid", fgColor="DB7311")
sheet["A4"].font = Font(name="Liberation Sans", size=12, color="000000")
sheet["A4"].alignment = Alignment(horizontal="center", vertical="center")
sheet["C5"] = "SHEET_SENTINEL"
buffer = BytesIO()
book.save(buffer)
with ZipFile(buffer) as archive:
    stable_zip(ROOT / "viewport-source.xlsx", {name: archive.read(name) for name in archive.namelist()})

files = ["viewport-source.docx", "viewport-source.xlsx"]
manifest = {
    "provenance": "Independent OOXML: Python stdlib DOCX package and openpyxl XLSX; no application import/export.",
    "sha256": {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in files},
    "word": {"primary": "VIEWPORT", "primaryColor": "D40A8E", "anchor": "ANCHOR", "anchorColor": "7541C8", "sentinel": "WORD_SENTINEL"},
    "calc": {"primary": "B2", "value": 25, "primaryColor": "20B2AA", "anchor": "A4", "anchorColor": "DB7311", "sentinel": "SHEET_SENTINEL"},
}
(ROOT / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
print(json.dumps(manifest, indent=2))
